There exists $\eta > 0$ such that if $s \in (0,2)$ then there exists a probability measure $
u$ supported on $\mathcal B$ with the following two properties:  egin{enumerate}[(i)] \item (Large Frostman dimension) For any ball $I$ of radius $r(I)$, we have  egin{equation} 
u(I) \ll_s r(I)^s. \end{equation} \item (Polynomial Fourier decay) For any ${ oldsymbol{\xi}} \in \mathbb Z^2$, we have \[ \widehat 
u({ oldsymbol{\xi}}) \ll_\eta (1 + \| { oldsymbol{\xi}} \|_\infty)^{-\eta}. \] \end{enumerate}

\eqref{point_sizeQJ} The first inequality was already shown in \eqref{Qest}. The second inequality then follows from the bounds \[ 1 \leqslant  rac{q_J({\alpha})}{q_{J-1}({\alpha})} \leqslant 2M. \] \eqref{point_dimFrostman} Fix $\mathbf x\in\mathbb R^2$ and $r>0.$ If $
u(B_r(\mathbf x))=0$ then the claim is straightforward, so in the rest of the proof we assume that $
u(B_r(\mathbf x))>0$. Define  egin{equation} Q_0:=\exp(J_0 \sigma_m(\kappa)) \qquad 	ext{ and } \qquad N:=\left\lfloor rac{\log r}{-\log Q_0}ightfloor+1. \end{equation} These definitions imply  egin{equation} Q_0^{-N} < r \leqslant Q_0^{1-N}. \end{equation} Let $C=C(\mathbf a,\mathbf b)$ be a cylinder set with $(\mathbf a,\mathbf b)\in\mathcal E^N$ such that  egin{equation} 
u\left(B_r(\mathbf x)\cap Cight)>0. \end{equation} Setting $J=J_0 N$ and $Q=\exp(J{\sigma}_m({\kappa}))=Q_0^N$ as above, point~\eqref{point_sizeQJ} of the lemma gives  egin{equation} Q^{1-2\varepsilon} \leqslant q_{J}(\mathbf a)\leqslant Q^{1+2\varepsilon}. \end{equation} We aim to provide an upper bound for the number of cylinder sets $C(\mathbf a,\mathbf b)$, where $(\mathbf a,\mathbf b) \in \mathcal E^N$, satisfying \eqref{lem_FD_nontrivial_intersection}. We do so by first bounding the number of possible tuples $\mathbf a$ and then the number of possible tuples $\mathbf b$. For each $\mathbf a\in [M]^{J}$, the cylinder set $C(\mathbf a)$ has length \[ |C(\mathbf a)| \geqslant  rac1{2Q^{2(1+2\varepsilon)}}, \] for the elements of $C(\mathbf a)$ are given by \eqref{alphaoft} for $t \in [0,1)$. Hence, there exist at most  egin{equation} 2r\cdot 2Q^{2(1+2\varepsilon)}+1 \leqslant 4Q^{1+4\varepsilon} +1 \leqslant 5Q^{1+4\varepsilon} \end{equation} tuples $\mathbf a$ such that the cylinder set $C(\mathbf a,\mathbf b)$ satisfies \eqref{lem_FD_nontrivial_intersection} for some $\mathbf b$. Now for a fixed $\mathbf a= (a_1, \ldots, a_{J}) \in [M]^{J}$, we find an upper bound for the number of different $J$--tuples $\mathbf b\in \mathcal V_{J}(\mathbf a)$ such that $C(\mathbf a,\mathbf b)$ satisfies \eqref{lem_FD_nontrivial_intersection}. Set $$\alpha=\alpha(\mathbf a) = [a_1,\ldots, a_{J}, M, M, \ldots].$$ For $\mathbf b = (b_1, \ldots, b_{J}) \in \mathcal V_{J}(\mathbf a)$, let \[ n = n(\mathbf a,\mathbf b) = b_{1}q_0(\alpha) + b_2q_1(\alpha) + \ldots + b_{J}q_{J-1}(\alpha) \] be the integer whose digits in the Ostrowski expansion~\eqref{Ostrowski_expansion_integers} with respect to $\alpha$ are the entries of $\mathbf b$. By Corollary~ef{cor_nag}, if $(\alpha,\gamma) \in C(\mathbf a,\mathbf b)$ then \[ \|\gamma-n(\mathbf a,\mathbf b)\alpha\| < 4M/ q_{J}(\mathbf a). \] This means that $\gamma$ belongs to an interval in $\mathbb R/\mathbb Z$ centred at $n(\mathbf a,\mathbf b)\alpha$ and of length at most $8 M/q_{J}(\mathbf a)$. Note from \eqref{useful} that if $\mathbf b_1, \mathbf b_2 \in \mathcal V_{J}(\mathbf a)$ then \[ |n(\mathbf a,\mathbf b_1)-n(\mathbf a,\mathbf b_2)| \leqslant 4M q_{J}(\mathbf a), \] so by \eqref{bad_lower_bound} the centres of the aforementioned intervals are separated by a distance of at least  egin{align*} \|n(\mathbf a,\mathbf b_1)\alpha-n(\mathbf a,\mathbf b_2)\alpha\| &\geqslant (2(M+1)|n(\mathbf a,\mathbf b_1)-n(\mathbf a,\mathbf b_2)|)^{-1}\ & \geqslant \left(8M(M+1) q_{J}(\mathbf a)ight)^{-1}. \end{align*} Thus, any interval of length $2r$ can intersect at most \[ 8M(M+1) Q^{1+2\varepsilon}\cdot 2r+2 \leqslant 16 (M+1)^2Q^{2\varepsilon} \] intervals centred at points $n(\mathbf a,\mathbf b)\alpha$ of length at most $8 M q_{J}(\mathbf a)^{-1}$. We conclude that for a fixed $\mathbf a$, there are at most $16 (M+1)^2 Q^{2\varepsilon}$ values of $\mathbf b$ such that the set $C(\mathbf a,\mathbf b)$ satisfies~\eqref{lem_FD_nontrivial_intersection}. Combining the two bounds, we deduce that the number of sets $C(\mathbf a,\mathbf b)$ that satisfy \eqref{lem_FD_nontrivial_intersection} is at most \[ 5Q^{1+4\varepsilon}\cdot 16 (M+1)^2 Q^{2\varepsilon} = 80 (M+1)^2 Q^{1+6\varepsilon}. \] For any such set the upper bound of Lemma~ef{lem_size_of_cylinder_set}, together with~\eqref{T_m_is_large}, gives  egin{equation} 
u(C(\mathbf a,\mathbf b)) < Q^{(1+2\varepsilon) (1-2\kappa)}. \end{equation} Using~\eqref{ub_nu_C} together with the upper bound for the number of cylinder sets satisfying~\eqref{lem_FD_nontrivial_intersection}, we infer the upper bound \[  egin{aligned} 
u\left(B_r(\mathbf x)ight) &< 80 (M+1)^2 Q^{1+6\varepsilon} \cdot Q^{(1+2\varepsilon)(1-2\kappa)} \ &= 80 (M+1)^2 \cdot Q^{2-2\kappa+4(2-\kappa)\varepsilon}. \end{aligned} \] Using \eqref{r_level}, this results in the upper bound \[ 
u\left(B_r(\mathbf x)ight) \leqslant 80 (M+1)^2 Q_0 r^{2\kappa-2-4(2-{\kappa})\varepsilon}. \]

\eqref{point_dimFrostman} Fix $\mathbf x\in\mathbb R^2$ and $r>0.$ If $
u(B_r(\mathbf x))=0$ then the claim is straightforward, so in the rest of the proof we assume that $
u(B_r(\mathbf x))>0$. Define  egin{equation} Q_0:=\exp(J_0 \sigma_m(\kappa)) \qquad 	ext{ and } \qquad N:=\left\lfloor rac{\log r}{-\log Q_0}ightfloor+1. \end{equation} These definitions imply  egin{equation} Q_0^{-N} < r \leqslant Q_0^{1-N}. \end{equation} Let $C=C(\mathbf a,\mathbf b)$ be a cylinder set with $(\mathbf a,\mathbf b)\in\mathcal E^N$ such that  egin{equation} 
u\left(B_r(\mathbf x)\cap Cight)>0. \end{equation} Setting $J=J_0 N$ and $Q=\exp(J{\sigma}_m({\kappa}))=Q_0^N$ as above, point~\eqref{point_sizeQJ} of the lemma gives  egin{equation} Q^{1-2\varepsilon} \leqslant q_{J}(\mathbf a)\leqslant Q^{1+2\varepsilon}. \end{equation} We aim to provide an upper bound for the number of cylinder sets $C(\mathbf a,\mathbf b)$, where $(\mathbf a,\mathbf b) \in \mathcal E^N$, satisfying \eqref{lem_FD_nontrivial_intersection}. We do so by first bounding the number of possible tuples $\mathbf a$ and then the number of possible tuples $\mathbf b$. For each $\mathbf a\in [M]^{J}$, the cylinder set $C(\mathbf a)$ has length \[ |C(\mathbf a)| \geqslant  rac1{2Q^{2(1+2\varepsilon)}}, \] for the elements of $C(\mathbf a)$ are given by \eqref{alphaoft} for $t \in [0,1)$. Hence, there exist at most  egin{equation} 2r\cdot 2Q^{2(1+2\varepsilon)}+1 \leqslant 4Q^{1+4\varepsilon} +1 \leqslant 5Q^{1+4\varepsilon} \end{equation} tuples $\mathbf a$ such that the cylinder set $C(\mathbf a,\mathbf b)$ satisfies \eqref{lem_FD_nontrivial_intersection} for some $\mathbf b$. Now for a fixed $\mathbf a= (a_1, \ldots, a_{J}) \in [M]^{J}$, we find an upper bound for the number of different $J$--tuples $\mathbf b\in \mathcal V_{J}(\mathbf a)$ such that $C(\mathbf a,\mathbf b)$ satisfies \eqref{lem_FD_nontrivial_intersection}. Set $$\alpha=\alpha(\mathbf a) = [a_1,\ldots, a_{J}, M, M, \ldots].$$ For $\mathbf b = (b_1, \ldots, b_{J}) \in \mathcal V_{J}(\mathbf a)$, let \[ n = n(\mathbf a,\mathbf b) = b_{1}q_0(\alpha) + b_2q_1(\alpha) + \ldots + b_{J}q_{J-1}(\alpha) \] be the integer whose digits in the Ostrowski expansion~\eqref{Ostrowski_expansion_integers} with respect to $\alpha$ are the entries of $\mathbf b$. By Corollary~ef{cor_nag}, if $(\alpha,\gamma) \in C(\mathbf a,\mathbf b)$ then \[ \|\gamma-n(\mathbf a,\mathbf b)\alpha\| < 4M/ q_{J}(\mathbf a). \] This means that $\gamma$ belongs to an interval in $\mathbb R/\mathbb Z$ centred at $n(\mathbf a,\mathbf b)\alpha$ and of length at most $8 M/q_{J}(\mathbf a)$. Note from \eqref{useful} that if $\mathbf b_1, \mathbf b_2 \in \mathcal V_{J}(\mathbf a)$ then \[ |n(\mathbf a,\mathbf b_1)-n(\mathbf a,\mathbf b_2)| \leqslant 4M q_{J}(\mathbf a), \] so by \eqref{bad_lower_bound} the centres of the aforementioned intervals are separated by a distance of at least  egin{align*} \|n(\mathbf a,\mathbf b_1)\alpha-n(\mathbf a,\mathbf b_2)\alpha\| &\geqslant (2(M+1)|n(\mathbf a,\mathbf b_1)-n(\mathbf a,\mathbf b_2)|)^{-1}\ & \geqslant \left(8M(M+1) q_{J}(\mathbf a)ight)^{-1}. \end{align*} Thus, any interval of length $2r$ can intersect at most \[ 8M(M+1) Q^{1+2\varepsilon}\cdot 2r+2 \leqslant 16 (M+1)^2Q^{2\varepsilon} \] intervals centred at points $n(\mathbf a,\mathbf b)\alpha$ of length at most $8 M q_{J}(\mathbf a)^{-1}$. We conclude that for a fixed $\mathbf a$, there are at most $16 (M+1)^2 Q^{2\varepsilon}$ values of $\mathbf b$ such that the set $C(\mathbf a,\mathbf b)$ satisfies~\eqref{lem_FD_nontrivial_intersection}. Combining the two bounds, we deduce that the number of sets $C(\mathbf a,\mathbf b)$ that satisfy \eqref{lem_FD_nontrivial_intersection} is at most \[ 5Q^{1+4\varepsilon}\cdot 16 (M+1)^2 Q^{2\varepsilon} = 80 (M+1)^2 Q^{1+6\varepsilon}. \] For any such set the upper bound of Lemma~ef{lem_size_of_cylinder_set}, together with~\eqref{T_m_is_large}, gives  egin{equation} 
u(C(\mathbf a,\mathbf b)) < Q^{(1+2\varepsilon) (1-2\kappa)}. \end{equation} Using~\eqref{ub_nu_C} together with the upper bound for the number of cylinder sets satisfying~\eqref{lem_FD_nontrivial_intersection}, we infer the upper bound \[  egin{aligned} 
u\left(B_r(\mathbf x)ight) &< 80 (M+1)^2 Q^{1+6\varepsilon} \cdot Q^{(1+2\varepsilon)(1-2\kappa)} \ &= 80 (M+1)^2 \cdot Q^{2-2\kappa+4(2-\kappa)\varepsilon}. \end{aligned} \] Using \eqref{r_level}, this results in the upper bound \[ 
u\left(B_r(\mathbf x)ight) \leqslant 80 (M+1)^2 Q_0 r^{2\kappa-2-4(2-{\kappa})\varepsilon}. \]

In this section, we will upper bound the decay of the Fourier transform of the measure constructed in Section~ef{subsection_ConstructionOfMeasures}, thereby establishing Theorem~ef{MainThm}~\eqref{MainThm_point_decay}. As Theorem~ef{MainThm}~\eqref{MainThm_point_Frostman_dimension} follows from Lemma~ef{lem_FD} point~\eqref{point_dimFrostman}, this will complete the proof of Theorem ef{MainThm}. \subsection{A comparison lemma} Given some basic data, the following lemma enables us to compare an integral with respect to a general measure to an integral with respect to Lebesgue measure, in two dimensions. This is analogous to its one-dimensional predecessor \cite[Lemma 5.3]{QR2003}.  egin{lemma} Let $M_1, M_2 \in (0,\infty)$, let $F(t,u)$ be a $C^1$ function on $B = [0,1] 	imes [-1,1]$ such that \[ \| F \|_\infty \leqslant 1, \qquad \| \partial_t F\|_\infty \leqslant M_1, \qquad \| \partial_u F \|_\infty \leqslant M_2, \] and put \[ m_2 = \int_B |F(t,u)|^2 {\,{m d}} t {\,{m d}} u. \] Let $
u$ be a probability measure on $B$, let $r > 0$, and denote by ${\Lambda}(r)$ the maximum of $
u(\mathcal R)$ as $\mathcal R$ ranges over axis-parallel filled rectangles of respective side lengths $r/M_1$ and $r/M_2$ in $B$. Then \[ \int_B |F(t,u)| {\,{m d}} 
u(t,u) \leqslant 3r + {\Lambda}(r) \left(2 +  rac{M_1}r +  rac{2M_2}r +  rac{m_2 M_1 M_2}{r^4} ight). \] \end{lemma}  egin{proof} Consider $\lfloor M_1/r floor \cdot \lfloor 2 M_2/r floor$ axis-parallel filled rectangles of respective side lengths $r/M_1$ and $r/M_2$, with non-overlapping interiors, whose union covers \[ \left[0, 1 - \:  rac{r}{M_1} ight] 	imes \left[-1, 1 - \:  rac{r}{M_2} ight]. \] Let $N$ be the number of these filled rectangles $\mathcal R$ on which \[ \max \{ |F(t,u)|: (t,u) \in \mathcal R \} \geqslant 3r. \] Within any such filled rectangle $\mathcal R$, there exists a pair $(t_0,u_0)$ such that $|F(t_0,u_0)| \geqslant 3r$. Thus, for any $(t,u) \in \mathcal R$, we have  egin{align*} |F(t,u)| &\geqslant |F(t_0,u_0)| - |F(t,u)-F(t,u_0)| - |F(t,u_0) - F(t_0,u_0)| \ &\geqslant 3r - r - r = r, \end{align*} by the mean value theorem. Therefore \[ m_2 \geqslant N  rac{r^2}{M_1 M_2} r^2 = N  rac{r^4}{M_1M_2}. \] At most $\lceil M_1/r ceil + \lceil 2M_2 / r ceil$ filled rectangles, further to our original ones, are needed to cover $B$, so  egin{align*} \int_B |F(t,u)| {\,{m d}} 
u (t,u) &\leqslant 3r + (N + \lceil M_1/r ceil + \lceil 2M_2 / r ceil) {\Lambda}(r) \ &\leqslant 3r + {\Lambda}(r) \left(2 +  rac{M_1}r +  rac{2M_2}r +  rac{m_2 M_1 M_2}{r^4} ight). \end{align*} \end{proof} \subsection{The Fourier transform of our measure} Let $k_1, k_2 \in \mathbb{Z}.$ The Fourier transform of $
u$ evaluated at the point $(k_1, k_2)$ is \[ \widehat 
u(k_1,k_2) = \int_{\mathbb R^2} e(-k_1 {\alpha} - k_2 {\gamma}) {\,{m d}} 
u({\alpha},{\gamma}). \] Since we cannot derive an explicit formula for the Fourier transform, our aim is to provide an estimate by writing $\widehat{
u}(k_1,k_2)$ as an integral of the form $\int_B F(t,u){\,{m d}} 
u(t,u)$ for some appropriate function $F(t,u)$ and then applying Lemma ef{ComparisonLemma}. In what follows, we use the parameters  egin{equation} \delta>0 	ext{ and } \phi=\delta/10. \end{equation} We also assume that the parameter $\varepsilon>0$ used in the construction of the measure $
u$, from the beginning of Section~ef{subsection_ConstructionOfMeasures}, is small enough to satisfy $\varepsilon<\phi/100$.  egin{remark} For the proof, we may assume that $\delta$ is large, see Remark~ef{rem_justification_concrete_eta}. For $\delta$ large enough, some of the cases considered below become simpler, for instance the cases described by~\eqref{third_scenario_description} or~\eqref{Case_2i_subcase_one}. For the sake of robustness, we also allow ${\delta}$ to be small. However, the busy reader may wish to assume that ${\delta}$ and hence $\phi$ is sufficiently large. For $\phi\geqslant 2$ (and $Q$ large enough, which we can assume without loss of generality), the inequality ~\eqref{third_scenario_description} implies that $q_J=q_J^*$ and $q_{J-1}=q_{J-1}^*$, and~\eqref{Case_2i_subcase_one} becomes $q_{J-1}=q_{J-1}^*$. The two simplified cases then reduce to the diagonal setting considered at the start of Subsection~ef{ss_diagonal_contribution}. \end{remark} With the pair $(k_1, k_2)$ fixed, let $K \geqslant 0$ be an even integer such that \[ Q_0^{KJ_0(2+\delta)} \leqslant\max \left(|k_1|, |k_2| Q_0^{KJ_0}ight)\leqslant Q_0^{(K+2)J_0(2+\delta)}. \] Also set \[ J := KJ_0 \qquad 	ext{ and } \qquad Q := Q_0^{J}. \] It then follows that  egin{equation} \max\left(|k_1|,|k_2| Qight)\asymp Q^{2+\delta}. \end{equation} Writing \[ {\alpha} = [a_1,a_2,\ldots], \qquad {\gamma} = \sum_{k=0}^\infty b_{k+1} D_k({\alpha}), \] as well as \[ \mathbf a = (a_1,\ldots,a_J), \qquad \mathbf b = (b_1,\ldots,b_J), \] we now have  egin{equation} {\,{m d}} 
u({\alpha},{\gamma}) = {\,{m d}} {\lambda}^K(\mathbf a,\mathbf b) {\,{m d}} 
u(t,u), \end{equation} where \[ t = [a_{J+1},a_{J+2},\ldots], \qquad u = \sum_{k=0}^\infty b_{J+k+1} D_k(t). \]  egin{lemma} We have \[ -t \leqslant u \leqslant 1-t. \] \end{lemma}  egin{proof} Observe that $u$ is given by an Ostrowski expansion in $t$. We use the fact that $D_0, D_1, D_2, \ldots$ alternate in sign, together with the identity \eqref{EndpointIdentity}. Further, as $R \mid J$, we have $b_{J+1} \leqslant a_{J+1} - 1 = a_1(t) - 1$. Using this information, we compute that \[ u \geqslant a_2(t) D_1(t) + a_4(t) D_3(t) + \dots = a_2(t) D_1(t) - D_2(t) = - t \] and  egin{align*} u &\leqslant (a_1(t) - 1) D_0(t) + a_3(t) D_2(t) + a_5(t) D_3(t) + \dots \ &= (a_1(t) - 1) D_0(t) - D_1(t) = 1 - t. \end{align*} \end{proof} Let us now fix  egin{equation}  egin{aligned} P = \left\{(t,u)\in [0,1]	imes\mathbb{R}: -t\leqslant u\leqslant 1-t ight\}\subset [0,1]	imes[-1,1]. \end{aligned} \end{equation}  egin{cor} The pushforward measure $
u$ is supported on $P$. \end{cor}  egin{remark} Clearly, translations by $\mathbb Z^2$ of $P$, defined by~\eqref{def_B} above, tile the plane $\mathbb R^2$, hence we can extend the measure $
u$ to $\mathbb R^2$ by periodicity. We could also consider this measure as being defined on $[0,1]^2$. Indeed, the parallelogram $P$ consists of two triangles: \[  egin{aligned} P&=T_1\cup T_2,\ T_1&:=\left\{(t,u)\in [0,1]	imes [0,1] : 0 \leqslant u\leqslant 1-t ight\},\ T_2&:=\left\{(t,u)\in [0,1]	imes [-1,0] : -t \leqslant u\leqslant 0 ight\}, \end{aligned} \] and $[0,1]^2$ is the union of $T_1$ and the translation of $T_2$ by the vector $(0,1)$. \end{remark} We now apply the analysis of \S ef{Ostrowski_section} to describe all quantities associated with pairs of the form $({\alpha},{\gamma})$ as functions of $(\mathbf a,\mathbf b)$ and $(t,u)$ and write $\widehat
u(k_1,k_2)$ in the desired form. It will be convenient to write \[ g = g(\mathbf a,\mathbf b,t)= \sum_{k=0}^{J-1} b_{k+1} D_k({\alpha}). \] In order to view $g$ as a function of $\mathbf a,\mathbf b,t$, we observe that  egin{align} &\gamma = g - D_{J-1}({\alpha}) u, \ &D_k({\alpha}) = q_k  rac{p_J + tp_{J-1}}{q_J + tq_{J-1}} - p_k \qquad (k \geqslant 0), \ &D_{J-1}({\alpha}) =  rac{(-1)^{J+1}}{q_J + tq_{J-1}}. \end{align} Indeed, using \eqref{DkRelation}, we get \[ \gamma = \sum_{k=0}^{J-1}b_{k+1}D_{k}({\alpha}) + \sum_{k=0}^{\infty}b_{J+k+1}D_{J+k}({\alpha}) = g - D_{J-1}({\alpha}) u, \] which is \eqref{eq2}. Equation \eqref{eq3} follows from \eqref{alphaoft} and the definition of $D_k$, while \eqref{eq4} follows from \eqref{eq3} and \eqref{pkqk}. By \eqref{factor} and the fact that $J$ is even, we now have  egin{align*} \widehat 
u(k_1,k_2) &= \int_{\mathbb R^2} e(-k_1 {\alpha} - k_2 {\gamma}) {\,{m d}} 
u({\alpha},{\gamma})\ &= \int_{\mathbb R^2} \int_{\mathcal E^K}e \left( -k_1  rac{p_J + t p_{J-1}}{q_J + tq_{J-1}} \: - k_2 \left(g(\mathbf a,\mathbf b,t) +  rac{u}{q_J + tq_{J-1}}ight) ight) \ & \qquad {\,{m d}}{\lambda}^K(\mathbf a,\mathbf b) {\,{m d}}
u(t,u) \ &= \int_B F(t,u) {\,{m d}} 
u(t,u), \end{align*} where  egin{align} 
otag F(t,u) &= \int_{\mathcal E^K} e \left( -k_1  rac{p_J + t p_{J-1}}{q_J + tq_{J-1}} \: - k_2 \left(g(\mathbf a,\mathbf b,t) +  rac{u}{q_J + tq_{J-1}}ight) ight) \ & \qquad {\,{m d}} {\lambda}^K(\mathbf a,\mathbf b). \end{align} By Lemma ef{ComparisonLemma}, to estimate $\widehat 
u(k_1,k_2)$ it now remains to bound the partial derivatives and second moment of our function $F$, as well as the measures of certain rectangles. \subsection{The partial derivatives} For $k \geqslant 0$, we have \[ \partial_t\alpha = \partial_t \left(  rac{p_J + t p_{J-1}}{q_J + tq_{J-1}} ight) =  rac{1}{(q_J+tq_{J-1})^2} \] and \[ \partial_t D_k({\alpha}) = q_k\cdot \partial_t {\alpha} =  rac{q_k}{(q_J+tq_{J-1})^2}. \] Hence  egin{equation} \partial_t g = \sum_{k=0}^{J-1}b_{k+1}\partial_t D_k({\alpha}) = (q_J+tq_{J-1})^{-2}\sum_{k=0}^{J-1}b_{k+1}q_k \end{equation} and \[ \partial_t \left(  rac{u}{q_J + tq_{J-1}}ight) =  rac{-u q_{J-1}}{(q_J+tq_{J-1})^2 }. \] The partial derivative of $F$ with respect to $t$ is therefore  egin{align*} &\partial_t F(t,u) \ &= \int_{\mathcal E^K}  rac{-2 \pi i}{(q_J+tq_{J-1})^2}\left(k_1 + k_2 \left(-uq_{J-1} + \sum_{k=0}^{J-1}b_{k+1}q_k ight) ight) \ & \qquad \cdot e \left( -k_1  rac{p_J + t p_{J-1}}{q_J + tq_{J-1}} - k_2 \left(g(\mathbf a,\mathbf b,t) +  rac{u}{q_J + tq_{J-1}}ight) ight) {\,{m d}} {\lambda}^K(\mathbf a,\mathbf b). \end{align*} By uniqueness of the Ostrowski expansion, if $(\mathbf a,\mathbf b) \in \mathcal E^K$ then \[ \sum_{k=0}^{J-1}b_{k+1}q_k < q_J, \] see \cite[Chapter II, \S 4]{RS1992}, and so \[ \left| -uq_{J-1} + \sum_{k=0}^{J-1}b_{k+1}q_k ight| < q_J + q_{J-1} \qquad (-1 \leqslant u \leqslant 1). \] Therefore \[ |\partial_t F(t,u)| \leqslant 2 \pi \left(  rac{|k_1|}{Q^{2(1-2\varepsilon)}} +  rac{2|k_2|}{Q^{1-2\varepsilon}} ight). \] The partial derivative of $F(t,u)$ with respect to $u$ is  egin{align*} &\partial_u F(t,u) \ &= \int_{\mathcal E^K} rac{-(2 \pi i) k_2}{q_J+tq_{J-1}} e\left( -k_1  rac{p_J + t p_{J-1}}{q_J + tq_{J-1}} - k_2 \left(g(\mathbf a,\mathbf b,t) +  rac{u}{q_J + tq_{J-1}}ight) ight) \ &\qquad {\,{m d}} {\lambda}^K(\mathbf a,\mathbf b), \end{align*} whence \[ |\partial_u F(t,u)| \leqslant  rac{2\pi |k_2|}{ Q^{1-2\varepsilon}}. \] \subsection{The second moment} With $B = [0,1] 	